const $=(sel,root=document)=>root.querySelector(sel), $$=(sel,root=document)=>[...root.querySelectorAll(sel)];
const stagedAttachments=new Map(),previewUrls=new Map();
let lastRenderedRoute=null;
const attachmentKey=form=>`${form.id}:${form.dataset.id}`;
function paintAttachmentPreview(form){const key=attachmentKey(form),box=form.querySelector('[data-preview]');if(!box)return;for(const url of previewUrls.get(key)||[])URL.revokeObjectURL(url);const files=stagedAttachments.get(key)||[],urls=files.map(f=>URL.createObjectURL(f));previewUrls.set(key,urls);box.innerHTML=files.map((f,i)=>`<div class="attachment-preview"><img src="${urls[i]}" alt="Xem trước ${esc(f.name)}"><span>${esc(f.name)}</span><button type="button" class="link-button" data-action="remove-staged-file" data-key="${esc(key)}" data-index="${i}">Gỡ ảnh</button></div>`).join('');}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('vi-VN').format(Number(n)||0)+' ₫';
const dateFmt=s=>s?new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'short',year:'numeric'}).format(new Date(s)):'';
const timeFmt=s=>s?new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour:'2-digit',minute:'2-digit'}).format(new Date(s)):'';
const dateTime=s=>s?`${timeFmt(s)} · ${dateFmt(s)}`:'';
const normalizeReportDate=s=>{const value=String(s||''),legacy=value.match(/^(\d{2})\/(\d{2})\/(\d{4})/);if(legacy)return `${legacy[3]}-${legacy[2]}-${legacy[1]}T00:00:00+07:00`;return /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/.test(value)?`${value.replace(' ','T')}:00+07:00`:value};
const reportTimestamp=s=>{const time=Date.parse(normalizeReportDate(s));return Number.isNaN(time)?0:time};
const reportDate=s=>{const value=String(s||''),normalized=normalizeReportDate(value);return Number.isNaN(Date.parse(normalized))?value:dateTime(new Date(Date.parse(normalized)).toISOString())};
const localInput=s=>{if(!s)return '';const d=new Date(s);return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d).replace(' ','T')};
const serviceName=s=>s==='DAYCARE'?'Chăm ban ngày':'Lưu trú';
