  dog:'<path d="M5.5 9 3.7 6.5a2.4 2.4 0 0 1 3.6-3L9 5h6l1.7-1.5a2.4 2.4 0 0 1 3.6 3L18.5 9v6a4 4 0 0 1-4 4h-5a4 4 0 0 1-4-4V9Z"/><circle cx="9" cy="11" r=".8" fill="currentColor"/><circle cx="15" cy="11" r=".8" fill="currentColor"/><path d="M10 15h4m-2-2v2"/>',
  cat:'<path d="m5 9-1-5 5 2h6l5-2-1 5v6a4 4 0 0 1-4 4H9a4 4 0 0 1-4-4V9Z"/><circle cx="9" cy="11" r=".8" fill="currentColor"/><circle cx="15" cy="11" r=".8" fill="currentColor"/><path d="m11 14 1 1 1-1m-6 1-3-1m3 3-3 1m12-3 3-1m-3 3 3 1"/>',
  home:'<path d="m3 10 9-7 9 7v9a2 2 0 0 1-2 2h-5v-6h-4v6H5a2 2 0 0 1-2-2v-9Z"/>',
  calendar:'<rect x="3.5" y="5" width="17" height="16" rx="2.5"/><path d="M8 3v4m8-4v4M4 9h16m-12 4h2m3 0h2m-7 4h2"/>',
  shield:'<path d="M12 3 19 6v5c0 4.6-2.8 8.2-7 10-4.2-1.8-7-5.4-7-10V6l7-3Z"/><path d="m9 12 2 2 4-4"/>',
  user:'<circle cx="12" cy="8" r="3.5"/><path d="M5 21v-1.5a7 7 0 0 1 14 0V21H5Z"/>',
