function reportCase(r){
 const s=state(),b=r.targetType==='BOOKING'?bookingBy(r.targetId):null,review=r.targetType==='REVIEW'?s.reviews.find(x=>x.id===r.targetId):null,l=r.targetType==='LISTING'?listingBy(r.targetId):null,permittedEvidence=r.status==='IN_REVIEW'&&['BOOKING','MESSAGE'].includes(r.targetType),message=r.targetType==='MESSAGE'?(bookingBy(r.bookingId)?.messages||[]).find(x=>x.id===r.targetId):null,operation=(s.adminOperations||[]).find(x=>x.reportId===r.id)||r.operation;
 const canComplete=Boolean(b&&b.status==='AWAITING_CONFIRMATION'&&b.payment?.attempts?.some(x=>x.status==='AUTHORIZED')),canRefund=Boolean(b&&['IN_PROGRESS','AWAITING_CONFIRMATION'].includes(b.status)&&b.payment?.attempts?.some(x=>x.status==='AUTHORIZED'));
 let targetInfo='';if(b)targetInfo=`<div class="admin-target-summary"><span>Booking status</span>${status(b.status)}<span>Thời gian dịch vụ</span><strong>${dateTime(b.start)} → ${timeFmt(b.end)}</strong><span>Listing</span><strong>${esc(listingBy(b.listingId)?.title||b.listingId)}</strong></div>`;else if(l)targetInfo=`<div class="admin-target-summary"><span>Listing</span><strong>${esc(l.title)}</strong><span>Trạng thái · version</span><strong>${esc(statusLabels[l.status]||l.status)} · v${l.version}</strong></div>`;else if(review)targetInfo=`<div class="admin-target-summary"><span>Đánh giá</span><strong>${review.rating} / 5 sao</strong><span>Trạng thái</span><strong>${esc(review.status||'VISIBLE')}</strong></div>`;else targetInfo=`<div class="admin-target-summary"><span>Target type</span><strong>${esc(r.targetType)}</strong><span>Reference</span><strong>${esc(r.targetId)}</strong></div>`;
 const evidence=permittedEvidence?`<details class="evidence-detail admin-evidence"><summary>${iconSvg('shield',16)} Xem evidence được phép</summary><div class="admin-evidence-body"><p>Evidence mock allowlist · chỉ hiển thị khi Admin ACTIVE và report IN_REVIEW. Mở được ghi vào lịch sử demo.</p>${b?`<dl><dt>Listing</dt><dd>${esc(listingBy(b.listingId)?.title||b.listingId)}</dd><dt>Trạng thái booking</dt><dd>${esc(b.status)}</dd><dt>Bắt đầu</dt><dd>${esc(dateTime(b.start))}</dd><dt>Kết thúc</dt><dd>${esc(dateTime(b.end))}</dd></dl>`:message?`<dl><dt>Người gửi</dt><dd>${esc(message.sender)}</dd><dt>Thời điểm</dt><dd>${esc(message.at)}</dd><dt>Nội dung</dt><dd>${esc(message.body)}</dd></dl>`:adminEmpty('Không có evidence','Target không có evidence được cho phép.')}</div></details>`:`<div class="admin-privacy-note">${iconSvg('shield',16)} Evidence riêng tư không khả dụng cho target/trạng thái này.</div>`;
 const actionControls=r.status==='OPEN'?`<div class="admin-action-row">${button('Bắt đầu xem xét','admin-reason-dialog',{id:r.id,kind:'secondary',small:true,title:'Start review',dialogKind:'start-review'})}${button('Dismiss report','admin-reason-dialog',{id:r.id,kind:'danger-soft',small:true,title:'Dismiss',dialogKind:'dismiss'})}</div>`:r.status==='IN_REVIEW'?`<form id="report-decision-form" data-id="${esc(r.id)}" class="admin-reason-inline"><div class="admin-form-grid"><div class="field"><label for="decision-type">Quyết định</label><select id="decision-type" name="decision">${b?`${canComplete?'<option value="COMPLETE">COMPLETE · tạo release operation</option>':''}${canRefund?'<option value="CANCEL_REFUND">CANCEL_REFUND · tạo cancellation operation</option>':''}<option value="DISMISS">Dismiss report only</option>`:'<option value="RESOLVE">Resolve report</option><option value="DISMISS">Dismiss report only</option>'}</select></div><div class="field"><label for="decision-reason">Lý do quyết định</label><textarea id="decision-reason" name="reason" required maxlength="1000" placeholder="Ghi căn cứ xử lý"></textarea></div></div>${b&&!canComplete&&!canRefund?`<div class="admin-inline-warning">Booking cần attempt AUTHORIZED và trạng thái phù hợp (COMPLETE: AWAITING_CONFIRMATION; CANCEL_REFUND: IN_PROGRESS hoặc AWAITING_CONFIRMATION).</div>`:''}<div data-error class="field-error" role="alert"></div><button class="button" type="submit">Lưu quyết định</button></form>`:`<div class="admin-closed-note">Report đã ${r.status==='RESOLVED'?'được resolve':'được dismiss'}; không có action trạng thái mới.</div>`;
 const moderation=l||review?r.status==='IN_REVIEW'?`<div class="admin-target-actions"><span>Moderation target</span>${button('Hide target','admin-reason-dialog',{id:r.id,kind:'danger-soft',small:true,dialogKind:'hide',disabled:r.targetType==='LISTING'&&l.status==='SUSPENDED'&&l.suspensionSource==='ADMIN'||r.targetType==='REVIEW'&&review.status==='HIDDEN'})}${button('Restore target','admin-reason-dialog',{id:r.id,kind:'secondary',small:true,dialogKind:'restore',disabled:r.targetType==='LISTING'&&!(l.status==='SUSPENDED'&&l.suspensionSource==='ADMIN')||r.targetType==='REVIEW'&&review.status!=='HIDDEN'})}</div>`:`<p class="admin-footnote">Hide/Restore chỉ khả dụng khi report IN_REVIEW và target là listing/review.</p>`:'';
 return `<section class="admin-panel admin-case-panel"><div class="admin-panel-head"><div><span class="admin-kicker">CASE DETAIL · ${esc(r.targetType)}</span><h2>${esc(r.id)}</h2><small>${esc(r.targetType)} · ${esc(r.targetId)} · Reporter ${esc(r.reporterId)}</small></div>${status(r.status)}</div><div class="admin-case-grid"><div><h3>Report details</h3><div class="admin-meta-list"><div><span>Reason code</span><code>${esc(r.reason)}</code></div><div><span>Submitted</span><strong>${esc(r.createdAt)}</strong></div><div><span>Description</span><p>${esc(r.description||'Người gửi không cung cấp mô tả.')}</p></div></div></div><div><h3>Target summary</h3>${targetInfo}</div></div>${evidence}${operation?`<div class="admin-operation-callout"><div><span class="admin-kicker">BOOKING OPERATION</span><strong>${esc(operation.kind)} · ${esc(operation.status)}</strong><small>Operation status tách biệt với report status ${esc(r.status)} · attempt ${Number(operation.attemptCount||0)}</small></div>${operation.status==='PENDING'?`<div class="admin-action-row">${button('Worker demo: thành công','admin-worker-result',{id:operation.id,kind:'secondary',small:true})}${button('Worker demo: manual review','admin-worker-fail',{id:operation.id,kind:'ghost',small:true})}</div>`:''}</div>`:''}${moderation}<div class="admin-history"><div class="admin-panel-head"><div><span class="admin-kicker">AUDIT TRAIL</span><h3>History</h3></div></div>${timeline({events:r.events||[]})}</div>${actionControls}</section>`;
}
function adminBookingExceptions(){
 if(!isAdmin())return accessPage('Booking exceptions yêu cầu persona ACTIVE');const s=state(),tab=s.ui.adminBookingTab||'completion',overdue=s.bookings.filter(b=>b.status==='AWAITING_CONFIRMATION'&&Date.parse(s.demoNow)-Date.parse(b.completionRequestedAt||'')>=72*60*60*1000),cancelOps=(s.adminOperations||[]).filter(o=>o.kind==='CANCEL_REFUND'&&o.status==='MANUAL_REVIEW'),selected=(s.adminOperations||[]).find(o=>o.id===s.ui.adminOperationId);
 const tabs=`<div class="admin-tabs" role="tablist"><button role="tab" aria-selected="${tab==='completion'}" class="${tab==='completion'?'active':''}" data-action="admin-booking-tab" data-tab="completion">Completion review <span>${overdue.length}</span></button><button role="tab" aria-selected="${tab==='cancellation'}" class="${tab==='cancellation'?'active':''}" data-action="admin-booking-tab" data-tab="cancellation">Cancellation manual review <span>${cancelOps.length}</span></button></div>`;
 const completionTable=`<div class="table-wrap admin-table-wrap"><table class="data-table admin-data-table"><thead><tr><th>Booking</th><th>Trạng thái</th><th>Đề nghị hoàn tất</th><th>Quá hạn</th><th>Operation</th><th></th></tr></thead><tbody>${overdue.map(b=>{const op=(s.adminOperations||[]).find(x=>x.bookingId===b.id&&x.kind==='RELEASE'&&['PENDING','PROCESSING','MANUAL_REVIEW','COMPLETED'].includes(x.status)),hours=Math.floor((Date.parse(s.demoNow)-Date.parse(b.completionRequestedAt))/3600000);return `<tr><td><strong>${esc(b.id)}</strong><small>${esc(listingBy(b.listingId)?.title||b.listingId)}</small></td><td>${status(b.status)}</td><td>${esc(dateTime(b.completionRequestedAt))}</td><td><span class="admin-overdue">${Math.max(0,hours-72)} giờ</span></td><td>${op?status(op.status):'<span class="admin-muted">Chưa tạo</span>'}</td><td>${op?button('Xem operation','admin-operation-open',{id:op.id,kind:'secondary',small:true}):button('Review completion','admin-reason-dialog',{id:b.id,kind:'secondary',small:true,dialogKind:'completion'})}</td></tr>`}).join('')||`<tr><td colspan="6">${adminEmpty('Không có completion quá hạn','Queue hiển thị booking AWAITING_CONFIRMATION đã chờ ít nhất 72 giờ.')}</td></tr>`}</tbody></table></div><p class="admin-footnote">Complete tạo release operation bất đồng bộ. Booking/payment chỉ đổi sau worker thành công; không có action retry release trong backend.</p>`;
 const cancellationTable=`<div class="table-wrap admin-table-wrap"><table class="data-table admin-data-table"><thead><tr><th>Operation</th><th>Booking</th><th>Source / reason</th><th>Attempts</th><th>Lỗi gần nhất</th><th></th></tr></thead><tbody>${cancelOps.map(o=>`<tr><td><strong>${esc(o.id)}</strong><small>${status(o.status)}</small></td><td>${esc(o.bookingId)}</td><td><code>${esc(o.source||'—')} · ${esc(o.reasonCode||'—')}</code></td><td>${Number(o.attemptCount||0)}</td><td>${esc(o.lastError||'—')}</td><td>${button('Mở operation','admin-operation-open',{id:o.id,kind:'secondary',small:true})}</td></tr>`).join('')||`<tr><td colspan="6">${adminEmpty('Không có cancellation cần review','Chỉ cancellation operation MANUAL_REVIEW được đưa vào queue retry.')}</td></tr>`}</tbody></table></div><p class="admin-footnote">Retry yêu cầu lý do và giữ gateway operation key. PAYMENT_STATE_MISMATCH cần đối soát trước, không có nút retry.</p>`;
 const operations=(s.adminOperations||[]).slice().reverse();return `${adminHeading('OPERATIONS','Booking exceptions','Hàng chờ backend cho completion review và cancellation manual review. Không thao tác payment trực tiếp.') }<div class="admin-summary-strip"><span><strong>${overdue.length}</strong> completion quá hạn</span><span><strong>${cancelOps.length}</strong> cancellation manual review</span><span><strong>${operations.filter(o=>o.status==='PENDING').length}</strong> operation pending</span><span class="admin-sample-tag">MOCK DATA</span></div><div class="admin-panel"><div class="admin-panel-head"><div><span class="admin-kicker">EXCEPTION QUEUES</span><h2>Hàng chờ can thiệp</h2></div></div>${tabs}${tab==='completion'?completionTable:cancellationTable}</div><section class="admin-panel admin-ops-panel"><div class="admin-panel-head"><div><span class="admin-kicker">ASYNC LIFECYCLE</span><h2>Operation status</h2></div><span class="admin-count">${operations.length} operation</span></div><div class="table-wrap admin-table-wrap"><table class="data-table admin-data-table"><thead><tr><th>Operation</th><th>Kind</th><th>Booking</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody>${operations.map(o=>`<tr><td><strong>${esc(o.id)}</strong><small>${esc(o.source||o.reasonCode||'')}</small></td><td>${esc(o.kind)}</td><td>${esc(o.bookingId)}</td><td>${status(o.status)}</td><td>${esc(o.completedAt||o.lastRetriedAt||o.createdAt||'—')}</td><td>${button('Chi tiết','admin-operation-open',{id:o.id,kind:'secondary',small:true})}</td></tr>`).join('')||'<tr><td colspan="6">Chưa có operation trong mock store.</td></tr>'}</tbody></table></div>${selected?adminOperationDetail(selected):`<div class="admin-detail-placeholder">${iconSvg('clock',22)}<span>Chọn operation để xem lịch sử. Worker result bên dưới chỉ là mô phỏng, không phải API Admin.</span></div>`}</section>`;
}
function adminOperationDetail(op){const b=bookingBy(op.bookingId);return `<section class="admin-operation-detail"><div><span class="admin-kicker">OPERATION DETAIL</span><h3>${esc(op.id)} · ${esc(op.kind)}</h3><p>${esc(op.reason||op.lastError||'Không có ghi chú operation.')}</p><div class="admin-operation-meta"><span>Booking <strong>${esc(op.bookingId)}</strong></span><span>Operation <strong>${esc(op.status)}</strong></span><span>Booking state <strong>${esc(b?.status||'—')}</strong></span><span>Reason code <strong>${esc(op.reasonCode||op.source||'—')}</strong></span></div>${(op.events||[]).length?`<div class="admin-operation-history"><strong>Operation history</strong>${timeline({events:op.events})}</div>`:''}</div>${op.kind==='CANCEL_REFUND'&&op.status==='MANUAL_REVIEW'?`<form id="admin-retry-form" data-id="${esc(op.id)}" class="admin-retry-form"><div class="field"><label for="retry-reason">Lý do retry · 10–500 ký tự</label><textarea id="retry-reason" name="reason" required minlength="10" maxlength="500" placeholder="Ghi căn cứ retry operation"></textarea></div><div data-error class="field-error"></div><button type="submit" class="button secondary small" ${op.reasonCode==='PAYMENT_STATE_MISMATCH'?'disabled title="Cần đối soát trước"':''}>Retry cancellation</button></form>`:op.status==='PENDING'?`<div class="admin-action-row">${button('Worker demo: thành công','admin-worker-result',{id:op.id,kind:'secondary',small:true})}${button('Worker demo: manual review','admin-worker-fail',{id:op.id,kind:'ghost',small:true})}</div>`:op.kind==='RELEASE'&&op.status==='MANUAL_REVIEW'?'<p class="admin-footnote">Backend hiện không có retry release action; operation chỉ xem trạng thái/lỗi.</p>':''}</section>`;}
function adminSystem(){if(!isAdmin())return accessPage('System monitoring yêu cầu persona ACTIVE');return `${adminHeading('SYSTEM','System monitoring','Điều hướng tới dashboard Laravel thật và API documentation. Prototype không dựng số liệu Pulse giả.') }<div class="admin-system-grid"><article class="admin-system-card"><span class="admin-system-icon lavender">${iconSvg('clock',23)}</span><div><span class="admin-kicker">LARAVEL PULSE</span><h2>Runtime monitoring</h2><p>Pulse được cấu hình với recorders trong Laravel. Tên card và dữ liệu runtime chưa được xác minh trong checkout; mở dashboard backend để kiểm tra trực tiếp.</p><code>/pulse</code><a class="button" href="/pulse" target="_blank" rel="noopener">Mở Laravel Pulse ↗</a></div></article><article class="admin-system-card"><span class="admin-system-icon sky">${iconSvg('clipboard',23)}</span><div><span class="admin-kicker">API REFERENCE</span><h2>API Documentation</h2><p>Tài liệu API được giới hạn bằng quyền Admin ACTIVE ở backend. Đây là route tài liệu, không phải màn hình xử lý dữ liệu.</p><code>/docs/api</code><a class="button secondary" href="/docs/api" target="_blank" rel="noopener">Mở API Documentation ↗</a></div></article></div><div class="admin-note-bar">${iconSvg('shield',18)}<span>Liên kết mở route backend trên origin hiện tại. Khi prototype được phục vụ ở origin riêng, mở trực tiếp <code>/pulse</code> hoặc <code>/docs/api</code> trên host Laravel đang chạy.</span></div><section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-kicker">OBSERVABILITY SCOPE</span><h2>Điều đã xác minh</h2></div><span class="admin-sample-tag">AS-IS BACKEND</span></div><div class="admin-system-facts"><p><strong>Pulse:</strong> 10 recorder được khai báo; quyền truy cập có test. Không xác nhận được exact cards/metrics hoặc runtime samples từ checkout hiện tại.</p><p><strong>API Docs:</strong> route <code>/docs/api</code> và <code>/docs/api.json</code> được gate cho Admin ACTIVE.</p><p><strong>Prototype:</strong> không hiển thị request rate, p95, lỗi payment hay queue count như metric thật.</p></div></section>`;}
function reportTargetLabel(type,id,s=state()){
 const b=s.bookings.find(x=>x.id===id);
 if(type==='BOOKING'&&b){const p=s.pets.find(x=>x.id===b.petId),l=s.listings.find(x=>x.id===b.listingId);return `${p?.name||'Thú cưng'} · ${l?.service==='BOARDING'?'Lưu trú':'Chăm ban ngày'} · ${dateFmt(b.start)} · ${statusLabels[b.status]||'Đang cập nhật'}`;}
 if(type==='LISTING'){const l=s.listings.find(x=>x.id===id);return l?.title||'Dịch vụ không còn khả dụng';}
 if(type==='REVIEW'){const r=s.reviews.find(x=>x.id===id),l=s.listings.find(x=>x.id===r?.listingId);return r?`${l?.title||'Dịch vụ'} · ${r.rating}/5 sao · ${r.body}`:'Đánh giá không còn khả dụng';}
 if(type==='MESSAGE'){for(const booking of s.bookings){const m=(booking.messages||[]).find(x=>x.id===id);if(m){const p=s.pets.find(x=>x.id===booking.petId);return `Tin nhắn trong lượt chăm ${p?.name||'thú cưng'} · ${m.sender}: ${m.body}`;}}return 'Tin nhắn không còn khả dụng';}
 return 'Mục tiêu không còn khả dụng';
}
function reportPage(){
 if(!isOwner())return accessPage('Báo cáo của bạn');
 const s=state(),ui=s.ui,all=s.reports.filter(r=>r.reporterId==='owner-01');
 const filtered=all.filter(r=>{
  const matchesStatus=!ui.ownerReportFilter||r.status===ui.ownerReportFilter;
  const haystack=[r.id,r.targetType,r.targetId,r.reason,r.description].join(' ').toLocaleLowerCase('vi');
  return matchesStatus&&(!ui.ownerReportQuery||haystack.includes(ui.ownerReportQuery.toLocaleLowerCase('vi')));
 }).sort((a,b)=>reportTimestamp(b.createdAt)-reportTimestamp(a.createdAt));
 const pageSize=10,totalPages=Math.max(1,Math.ceil(filtered.length/pageSize)),page=Math.min(Math.max(1,Number(ui.ownerReportPage)||1),totalPages),start=(page-1)*pageSize;
 const visible=filtered.slice(start,start+pageSize),selected=all.find(r=>r.id===ui.ownerReportId);
 const statusCounts=['OPEN','IN_REVIEW','RESOLVED','DISMISSED'].map(key=>[key,all.filter(r=>r.status===key).length]);
 const reasonNames={SAFETY_CONCERN:'Quan ngại về an toàn',INACCURATE_CONTENT:'Thông tin chưa chính xác',HARASSMENT:'Hành vi không phù hợp',OTHER:'Khác'};
 const targetNames={BOOKING:'Lượt đặt',LISTING:'Dịch vụ',REVIEW:'Đánh giá',MESSAGE:'Tin nhắn'};
 const reportBookings=s.bookings.filter(b=>b.ownerId==='owner-01'),reportListings=s.listings.filter(l=>l.status==='ACTIVE'),reportReviews=s.reviews;
 const targetOptions={BOOKING:reportBookings.map(b=>[b.id,reportTargetLabel('BOOKING',b.id,s)]),LISTING:reportListings.map(l=>[l.id,reportTargetLabel('LISTING',l.id,s)]),REVIEW:reportReviews.map(r=>[r.id,reportTargetLabel('REVIEW',r.id,s)]),MESSAGE:reportBookings.flatMap(b=>(b.messages||[]).map(m=>[m.id,reportTargetLabel('MESSAGE',m.id,s)]))};
 const initialType=ui.reportPrefill?'BOOKING':'BOOKING';
 const reportForm=`<details class="owner-report-submit" ${ui.reportPrefill?'open':''}><summary><span><strong>Gửi báo cáo mới</strong><small>Chọn mục tiêu và cung cấp thông tin liên quan</small></span><span aria-hidden="true">＋</span></summary><form id="report-form" class="owner-report-form"><div class="form-grid"><div class="field"><label for="report-target-type">Mục tiêu báo cáo</label><select id="report-target-type" name="targetType"><option value="BOOKING" ${initialType==='BOOKING'?'selected':''}>Lượt đặt</option><option value="LISTING">Dịch vụ</option><option value="REVIEW">Đánh giá</option><option value="MESSAGE">Tin nhắn</option></select></div><div class="field"><label for="report-target">Chọn mục tiêu</label><select id="report-target" name="targetId">${targetOptions[initialType].map(([id,label])=>`<option value="${esc(id)}" ${ui.reportPrefill===id?'selected':''}>${esc(label)}</option>`).join('')}</select></div><div class="field"><label for="report-reason">Lý do</label><select id="report-reason" name="reason" required><option value="">Chọn lý do</option><option value="SAFETY_CONCERN">Quan ngại về an toàn</option><option value="INACCURATE_CONTENT">Thông tin chưa chính xác</option><option value="HARASSMENT">Hành vi không phù hợp</option><option value="OTHER">Khác</option></select></div><div class="field full"><label for="report-description">Mô tả thêm (tùy chọn)</label><textarea id="report-description" name="description" maxlength="2000" placeholder="Chỉ cung cấp thông tin liên quan đến báo cáo"></textarea><small>Không thêm thông tin sức khỏe, liên hệ, mật khẩu hoặc tài chính không liên quan.</small></div></div><div data-error class="field-error" role="alert"></div><button class="button" type="submit">Gửi báo cáo</button></form></details>`;
 const rows=visible.map(r=>`<article class="owner-report-row"><div class="owner-report-identity"><strong>${esc(r.id)}</strong><span>${targetNames[r.targetType]||esc(r.targetType)} · ${esc(reportTargetLabel(r.targetType,r.targetId,s))}</span></div><p class="owner-report-meta">${esc(reasonNames[r.reason]||r.reason)} <span aria-hidden="true">·</span> ${esc(reportDate(r.createdAt))}</p><div class="owner-report-status">${status(r.status)}</div><button class="button secondary small" data-action="owner-report-open" data-id="${esc(r.id)}" aria-label="Xem chi tiết báo cáo ${esc(r.id)}">Chi tiết</button></article>`).join('');
 const detail=selected?`<section class="owner-report-detail card" id="owner-report-detail" aria-live="polite"><div class="owner-report-detail-head"><div><p class="eyebrow">CHI TIẾT BÁO CÁO</p><h2>${esc(selected.id)} <span>${targetNames[selected.targetType]||esc(selected.targetType)}</span></h2></div><div class="owner-report-detail-actions"><button class="button ghost small" data-action="owner-report-close" aria-label="Đóng chi tiết">Đóng</button></div></div><div class="owner-report-facts"><p><strong>Trạng thái</strong>${status(selected.status)}</p><p><strong>Lý do</strong>${esc(reasonNames[selected.reason]||selected.reason)}</p><p><strong>Mục tiêu được báo cáo</strong>${esc(reportTargetLabel(selected.targetType,selected.targetId,s))}</p><p><strong>Ngày gửi</strong>${esc(reportDate(selected.createdAt))}</p></div>${selected.description?`<div class="owner-report-description"><strong>Mô tả đã gửi</strong><p>${esc(selected.description)}</p></div>`:''}<div class="owner-report-history"><h3>Lịch sử cập nhật</h3>${timeline({events:selected.events||[]})}</div></section>`:'';
 const countLine=statusCounts.map(([key,count])=>`<span class="owner-report-count-inline">${statusLabels[key]} <strong>${count}</strong></span>`).join('');
 return `${pageTitle('An toàn cộng đồng','Báo cáo của bạn','Theo dõi trạng thái và lịch sử báo cáo đã gửi.') }<section class="owner-report-list-section" aria-labelledby="owner-report-list-title"><div class="section-heading"><div><h2 id="owner-report-list-title">Danh sách báo cáo <small>${all.length}</small></h2><p>${filtered.length?`Hiển thị ${start+1}–${Math.min(start+pageSize,filtered.length)} trong ${filtered.length}`:'Không có báo cáo phù hợp'}</p></div><div class="owner-report-header-actions"><div class="owner-report-counts-inline" aria-label="Tổng quan theo trạng thái">${countLine}</div>${reportForm}</div></div><form id="owner-report-filter-form" class="owner-report-filters"><div class="field"><label for="owner-report-query">Tìm báo cáo</label><input id="owner-report-query" name="query" type="search" maxlength="100" value="${esc(ui.ownerReportQuery||'')}" placeholder="Mã, mục tiêu hoặc nội dung"></div><div class="field"><label for="owner-report-status">Trạng thái</label><select id="owner-report-status" name="status"><option value="">Tất cả trạng thái</option>${['OPEN','IN_REVIEW','RESOLVED','DISMISSED'].map(key=>`<option value="${key}" ${ui.ownerReportFilter===key?'selected':''}>${statusLabels[key]}</option>`).join('')}</select></div><button class="button secondary" type="submit">Lọc</button></form><div class="owner-report-list" aria-live="polite">${rows||`<div class="owner-report-empty"><strong>${all.length?'Không tìm thấy báo cáo':'Bạn chưa gửi báo cáo'}</strong><p>${all.length?'Thử đổi từ khóa hoặc trạng thái lọc.':'Khi cần hỗ trợ, bạn có thể gửi báo cáo mới ở phía dưới.'}</p></div>`}</div>${filtered.length>pageSize?`<nav class="owner-report-pagination" aria-label="Phân trang báo cáo"><span>Trang ${page} / ${totalPages}</span><div><button class="button secondary small" data-action="owner-report-page" data-page="${page-1}" ${page===1?'disabled':''}>Trước</button><button class="button secondary small" data-action="owner-report-page" data-page="${page+1}" ${page===totalPages?'disabled':''}>Tiếp</button></div></nav>`:''}</section>${detail}`;
}
function reviewPage(id){if(!isOwner())return accessPage('Viết đánh giá');const b=bookingBy(id);if(!b||b.status!=='COMPLETED')return `${pageTitle('Đánh giá','Chưa đủ điều kiện','Chỉ Owner của lượt đặt đã hoàn tất mới được đánh giá.')}${link('Xem lượt đặt','owner/bookings')}`;if(b.reviewId)return `${pageTitle('Đánh giá','Đã gửi đánh giá','Mỗi booking chỉ có một đánh giá. Ẩn đánh giá cũ không tạo quyền gửi lần nữa.')}${link('Về lượt đặt','owner/booking/'+id)}`;return `${pageTitle('Đánh giá dịch vụ','Chia sẻ trải nghiệm của bạn','Đánh giá chỉ mở sau khi booking COMPLETED.') }<div class="card" style="max-width:700px"><h2>${esc(listingBy(b.listingId)?.title||'Dịch vụ')}</h2><form id="review-form" data-id="${id}" class="stack"><div class="field"><label for="review-rating">Mức đánh giá</label><select id="review-rating" name="rating" required><option value="">Chọn số sao</option><option value="5">5 · Rất tốt</option><option value="4">4 · Tốt</option><option value="3">3 · Bình thường</option><option value="2">2 · Chưa tốt</option><option value="1">1 · Kém</option></select></div><div class="field"><label for="review-body">Nhận xét (tùy chọn)</label><textarea id="review-body" name="body" maxlength="1000" placeholder="Chia sẻ điều hữu ích cho chủ nuôi khác"></textarea></div><div data-error class="field-error"></div><button class="button" type="submit">Gửi đánh giá</button></form></div>`;}
function accessPage(title){return `${pageTitle('Khu vực riêng tư',title,'Bạn đang ở persona không có quyền xem nội dung này.')}${notice('Nội dung riêng tư không được tải khi sai persona. Hãy dùng Prototype persona để chuyển sang tài khoản có quyền.','warning','!')}${link('Về khám phá','discover')}`;}
function notFound(){return `${pageTitle('Không tìm thấy','Trang này chưa có trong prototype','Hãy quay lại trang khám phá hoặc dùng điều hướng theo vai trò.')}${link('Về khám phá','discover')}`;}

function clearAttachments(key){stagedAttachments.delete(key);for(const url of previewUrls.get(key)||[])URL.revokeObjectURL(url);previewUrls.delete(key);}
function render(){
 const r=route();if((r==='admin'||r.startsWith('admin/'))&&r!==lastRenderedRoute)update(s=>{s.ui.adminViewState='ready'});lastRenderedRoute=r;let out;
 if(r==='discover')out=discover();
 else if(r==='auth')out=authPage();
 else if(r.startsWith('listing/'))out=listingDetail(r.split('/')[1]);
 else if(r.startsWith('caregiver/public/'))out=publicCaregiverDetail(r.split('/')[2]);
 else if(r==='owner/pets')out=petManager();
 else if(r==='owner/bookings')out=bookingList('owner');
 else if(r.startsWith('owner/booking/'))out=bookingDetail(r.split('/')[2],'owner');
 else if(r.startsWith('owner/checkout/'))out=checkout(r.split('/')[2]);
 else if(r==='owner/reports')out=reportPage();
 else if(r==='owner/profile')out=ownerProfile();
 else if(r.startsWith('owner/review/'))out=reviewPage(r.split('/')[2]);
 else if(r==='caregiver')out=caregiverHome();
 else if(r==='caregiver/profile')out=caregiverProfile();
 else if(r==='caregiver/bookings')out=caregiverBookings();
 else if(r.startsWith('caregiver/booking/'))out=bookingDetail(r.split('/')[2],'caregiver');
 else if(r==='caregiver/listings')out=caregiverListings();
 else if(r.startsWith('caregiver/listing/'))out=listingEditor(r.split('/')[2]);
 else if(r==='caregiver/availability')out=availability();
 else if(r==='admin'||r==='admin/')out=adminDashboard();
 else if(r==='admin/listings')out=adminListings();
 else if(r==='admin/reports')out=adminReports();
 else if(r==='admin/booking-exceptions')out=adminBookingExceptions();
 else if(r==='admin/system')out=adminSystem();
 else out=notFound();
 $('#app').innerHTML=r.startsWith('admin')?adminShell(out):shell(out);
 if(r.startsWith('admin'))$('#admin-modal-reason')?.focus();
 const activePetEdit=$('#pet-editor');if(activePetEdit&&window._petEditor) {activePetEdit.innerHTML=petEditor(window._petEditor);window._petEditor=null;activePetEdit.scrollIntoView({block:'center',behavior:'smooth'});}
 document.title=(out.match(/<h1[^>]*>(.*?)<\/h1>/)?.[1]?.replace(/<[^>]*>/g,'')||'PETTEL')+' · PETTEL Prototype';
}
function toast(message,type='success'){
 const region=$('#toast-region'),el=document.createElement('div');el.className='toast '+(type==='error'?'error':type==='info'?'info':'');el.setAttribute('role',type==='error'?'alert':'status');el.textContent=message;region.append(el);setTimeout(()=>el.remove(),4200);
}
function inlineError(form,message){const box=form.querySelector('[data-error]');if(box)box.textContent=message;else toast(message,'error');}
